-- services/common/data/2026-08_semantic_core_import_v2.sql
-- Повторный импорт обновлённого семантического ядра из того же файла
-- 'все запросы из СЯ для БД.xlsx' (лист 'Семантическое ядро', версия от 04.08.2026).
-- Источник: 4086 строк в файле -> 4085 уникальных непустых запросов.
--
-- Что нового по сравнению с прошлым импортом (2026-07_semantic_core_import.sql):
--   1. Новая колонка файла 'Тема или Интент' -> topic_id (справочник common.topics,
--      создаётся этим файлом впервые).
--   2. 2 новых значения hub_name: 'Атака', 'Защита (без DDoS)'.
--   3. Новых значений в common.clusters НЕТ — все 33 значения колонки 'Кластер'
--      в этом файле уже есть в справочнике.
--
-- Маппинг колонок файла -> common.requests: тот же, что и в прошлый раз, плюс:
--   'Тема или Интент' -> topic_id (через common.topics)
--
-- Политика связей: как и раньше, request — единственное обязательное поле,
-- несовпавшие связи остаются NULL, строка всё равно импортируется.
--
-- Для НОВЫХ запросов (ещё не было в common.requests) — INSERT со всеми 5 связями
-- сразу (hub_id/cluster_id/cluster_topvisor_id/type_request_id/topic_id).
-- Для УЖЕ СУЩЕСТВУЮЩИХ запросов — трогаем только topic_id, и только если он ещё
-- NULL (шаг 6b). hub_id/cluster_id/cluster_topvisor_id/type_request_id уже
-- проставленных строк НЕ перезаписываются нигде в этом файле.
--
-- Безопасно перезапускать любое количество раз.

BEGIN;

-- 0. Синхронизация sequence для hubs/requests (см. миграцию прошлого раза —
-- common.clusters по-прежнему без sequence, но в этом прогоне новых кластеров нет,
-- поэтому синхронизация для неё не нужна).
SELECT setval(pg_get_serial_sequence('common.hubs', 'hub_id'), COALESCE((SELECT MAX(hub_id) FROM common.hubs), 1));
SELECT setval(pg_get_serial_sequence('common.requests', 'request_id'), COALESCE((SELECT MAX(request_id) FROM common.requests), 1));

-- 1. Новый справочник тем/интентов (создаётся впервые)
CREATE TABLE IF NOT EXISTS common.topics (
    topic_id   SERIAL PRIMARY KEY,
    topic_name TEXT NOT NULL UNIQUE
);
COMMENT ON TABLE common.topics IS 'Справочник тем/интентов запроса (колонка Тема или Интент в исходном файле СЯ).';

-- 2. Новая колонка в common.requests
ALTER TABLE common.requests ADD COLUMN IF NOT EXISTS topic_id INTEGER REFERENCES common.topics(topic_id);
COMMENT ON COLUMN common.requests.topic_id IS 'Тема/интент запроса (common.topics), из колонки Тема или Интент файла СЯ.';

-- 3. Новые значения hub_name
INSERT INTO common.hubs (hub_name)
SELECT v.name FROM (VALUES
    ('Атака'),
    ('Защита (без DDoS)')
) AS v(name)
WHERE NOT EXISTS (SELECT 1 FROM common.hubs h WHERE h.hub_name = v.name);

-- 4. Все значения 'Тема или Интент' из файла -> common.topics (справочник новый, пустой)
INSERT INTO common.topics (topic_name) VALUES
    ('bruteforce'),
    ('cdn'),
    ('ddos атака'),
    ('icmp'),
    ('ip'),
    ('kaminsky'),
    ('mitm'),
    ('phishing'),
    ('ransomware'),
    ('slowloris'),
    ('spam'),
    ('sql'),
    ('syn_flood'),
    ('vds'),
    ('vps'),
    ('xss'),
    ('виды атак'),
    ('домен'),
    ('другой вид атаки'),
    ('защита'),
    ('интернет'),
    ('кибератака'),
    ('массированная'),
    ('сайт'),
    ('сервер'),
    ('сети'),
    ('телефон'),
    ('удалить'),
    ('хакер'),
    ('хостинг')
ON CONFLICT (topic_name) DO NOTHING;

-- 5. Staging: сырые строки файла как есть
CREATE TEMP TABLE _semantic_core_import_v2 (
    seq INTEGER,
    request TEXT,
    hub_name TEXT,
    cluster_name TEXT,
    topic_name TEXT,
    topvisor_group_name TEXT,
    type_name TEXT
);

