-- 6a. Новые запросы (которых ещё нет в common.requests) — вставляем со всеми связями
INSERT INTO common.requests (request, hub_id, cluster_id, cluster_topvisor_id, type_request_id, topic_id)
SELECT DISTINCT ON (s.request)
    s.request, h.hub_id, c.cluster_id, ct.cluster_topvisor_id, tr.type_request_id, tp.topic_id
FROM _semantic_core_import_v2 s
LEFT JOIN common.hubs h ON h.hub_name = s.hub_name
LEFT JOIN common.clusters c ON c.cluster_name = s.cluster_name
LEFT JOIN common.clusters_topvisor ct ON ct.cluster_topvisor_name = s.topvisor_group_name
    AND ct.project_topvisor_id IN (7093082, 0)
LEFT JOIN common.type_request tr ON tr.name_type = s.type_name
LEFT JOIN common.topics tp ON tp.topic_name = s.topic_name
ORDER BY s.request, s.seq
ON CONFLICT (request) DO NOTHING;

-- 6b. Уже существующие запросы — дозаполняем ТОЛЬКО topic_id, и только если он ещё
-- пуст. Остальные поля существующих строк не трогаем.
UPDATE common.requests cr
SET topic_id = tp.topic_id
FROM _semantic_core_import_v2 s
JOIN common.topics tp ON tp.topic_name = s.topic_name
WHERE cr.request = s.request
  AND cr.topic_id IS NULL
  AND s.topic_name IS NOT NULL;

DROP TABLE _semantic_core_import_v2;

COMMIT;
